"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41917"],{22820(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_divulgacao.justificativa_muito_longa","status":422,"titulo":"A justificativa excede o limite de caracteres"},"descricao":{"codigo":"uniplus.selecao.configuracao_divulgacao.justificativa_muito_longa","requisitos":[],"oQueAconteceu":["A justificativa da divulga\xe7\xe3o p\xfablica \xe9 um texto livre de neg\xf3cio, com no m\xe1ximo 1000\\ncaracteres. O limite \xe9 conferido sobre o texto j\xe1 normalizado: sem espa\xe7os nas bordas e na forma\\nde composi\xe7\xe3o padr\xe3o de caracteres acentuados. O texto enviado passa desse limite.","A confer\xeancia vale para qualquer justificativa enviada, mesmo quando o `NOME` n\xe3o est\xe1 na lista.\\nA recusa vem junto das demais viola\xe7\xf5es do mesmo pedido, no array `errors[]`, e pode aparecer ao\\nlado de\\n[`justificativa_caractere_invalido`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_caractere_invalido),\\nde\\n[`campos_publicos_vazio`](/erros/uniplus.selecao.configuracao_divulgacao.campos_publicos_vazio), de\\n[`campo_nao_permitido`](/erros/uniplus.selecao.configuracao_divulgacao.campo_nao_permitido), de\\n[`numero_inscricao_obrigatorio`](/erros/uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio)\\ne de\\n[`formas_de_identificacao_excludentes`](/erros/uniplus.selecao.configuracao_divulgacao.formas_de_identificacao_excludentes).\\nN\xe3o vem junto de\\n[`justificativa_obrigatoria`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_obrigatoria),\\nque exige a justificativa ausente."],"comoResolver":["Resuma a justificativa para at\xe9 1000 caracteres e reenvie. Se a resposta trouxer mais de uma\\nviola\xe7\xe3o em `errors[]`, corrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o da divulga\xe7\xe3o p\xfablica do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao divulgacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);